 async function saveEntry(e:React.FormEvent){
  e.preventDefault();setActionMessage("");
  const value=Number(entryValue);
  if(!supabase||!dbUnit||!canManage){setActionMessage("Seu usuário não tem permissão financeira para esta unidade.");return}
  if(closedDay){setActionMessage("Este dia já foi fechado. Não é possível lançar novas movimentações.");return}
  if(!Number.isFinite(value)||value<=0||entryDesc.trim().length<3){setActionMessage("Informe descrição e valor válido.");return}
  setSaving(true);
  const payload={data_lancamento:operationDate,tipo:view==="despesas"?"saida":entryType,categoria:entryCategory.trim(),descricao:entryDesc.trim(),valor:value,forma_pagamento:entryMethod};
  const {error,data}=editingEntry
    ?await supabase.from("financeiro_lancamentos").update(payload).eq("id",editingEntry.id).eq("estabelecimento_id",dbUnit.id).is("cancelado_em",null).select("id").single()
    :await supabase.from("financeiro_lancamentos").insert({...payload,estabelecimento_id:dbUnit.id}).select("id").single();
  if(error||!data)setActionMessage("Falha ao salvar: "+(error?.message||"Operação não confirmada."));
  else{setActionMessage(editingEntry?"Lançamento atualizado com sucesso.":"Lançamento gravado com sucesso.");setEntryDesc("");setEntryValue("");setDisplayForm(false);setEditingEntry(null);await reloadFinance()}
  setSaving(false);
 }
function openEditEntry(row:Entry){if(!canManageRow(row)){setActionMessage("Movimentação sem permissão ou pertencente a um dia fechado.");return}setEditingEntry(row);setEntryType(row.type);setEntryCategory(row.category);setEntryDesc(row.desc);setEntryValue(String(row.amount));setEntryMethod(row.method);setOperationUnit(row.unit);setOperationDate(row.date);setActionMessage("")}
 async function cancelEntry(row:Entry){if(!supabase||!canManageRow(row)){setActionMessage("Movimentação sem permissão ou pertencente a um dia fechado.");return}
 if(!window.confirm("Cancelar este lançamento de "+money(row.amount)+" de "+unitName(row.unit)+"? Ele permanecerá no histórico de auditoria e deixará de entrar nos totais."))return;
 setCancellingId(row.id);setActionMessage("");
 const unitId=unitsDb.find(u=>u.slug===row.unit)?.id;
 const {error,data}=await supabase.from("financeiro_lancamentos").update({cancelado_em:new Date().toISOString()}).eq("id",row.id).eq("estabelecimento_id",unitId!).is("cancelado_em",null).select("id").single();
 setCancellingId(null);if(error||!data)setActionMessage("Não foi possível cancelar: "+(error?.message||"Nenhum lançamento alterado."));else{setActionMessage("Lançamento cancelado e preservado no histórico.");await reloadFinance()}
 }
  async function saveClosing(e:React.FormEvent){
  e.preventDefault();setActionMessage("");
  if(!supabase||!dbUnit||!canManage||closedDay){setActionMessage("Sem autorização ou dia já fechado.");return}
  const start=Number(balanceStart),count=Number(balanceCounted);
  if(balanceCounted===""||!Number.isFinite(count)||count<0||!Number.isFinite(start)||start<0){setActionMessage("Informe saldos válidos para o fechamento.");return}
  setSaving(true);
  const {error}=await supabase.from("financeiro_fechamentos").insert({estabelecimento_id:dbUnit.id,data_fechamento:operationDate,saldo_inicial:start,saldo_informado:count,entradas:dailyIn,saidas:dailyOut,saldo_calculado:start+dailyIn-dailyOut,observacao:closingNote.trim()||null});
  if(error)setActionMessage("Falha ao fechar: "+error.message);
  else{setActionMessage("Fechamento salvo no Supabase.");setBalanceCounted("");setClosingNote("");await reloadFinance()}
  setSaving(false);
 }
