 const days=Array.from({length:period==="7"?7:period==="30"?30:Math.max(1,Math.round((Date.now()-new Date(dateStart(period)+"T12:00:00").getTime())/86400000)+1)},(_,i)=>{const d=new Date(dateStart(period)+"T12:00:00");d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)}).filter(d=>d<=new Date().toISOString().slice(0,10));
